INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ1', 'analyse-fondamentale', 'intro', 1, 'Dans le MarketDriverVisualizer, la chaîne causale s''affiche comme :', '[{"id":"a","label":"Un tableau de chiffres"},{"id":"b","label":"Driver → Canal → Actif impacté → Invalidation"},{"id":"c","label":"Un graphique en camembert"},{"id":"d","label":"Une liste alphabétique"}]'::jsonb, 'b', 'La logique est la transmission causale avec condition de sortie explicite.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ2', 'analyse-fondamentale', 'intro', 1, 'Le MacroRegimeRadar affiche 4 régimes principaux. Lequel correspond à « croissance forte + inflation modérée » ?', '[{"id":"a","label":"Stagflation"},{"id":"b","label":"Récession"},{"id":"c","label":"Goldilocks"},{"id":"d","label":"Déflation"}]'::jsonb, 'c', 'Goldilocks = croissance saine + inflation contrôlée.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ3', 'analyse-fondamentale', 'intro', 2, 'Dans le MarketDriverVisualizer, l''« invalidation » représente :', '[{"id":"a","label":"Une erreur de calcul"},{"id":"b","label":"La condition de sortie qui rend la thèse caduque"},{"id":"c","label":"Un achat forcé"},{"id":"d","label":"Une news positive"}]'::jsonb, 'b', 'C''est le mécanisme de gestion du risque : quand la thèse est invalidée, on sort.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ4', 'analyse-fondamentale', 'intro', 2, 'Sur le MacroRegimeRadar, l''axe « Liquidité » mesure principalement :', '[{"id":"a","label":"Le volume des transactions"},{"id":"b","label":"La politique monétaire (QE/QT, taux)"},{"id":"c","label":"Le nombre d''employés"},{"id":"d","label":"Le PIB"}]'::jsonb, 'b', 'Liquidité = politique monétaire, spreads de crédit, conditions financières.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ5', 'analyse-fondamentale', 'intro', 2, 'Le régime « Stagflation » sur le radar implique généralement :', '[{"id":"a","label":"Actions haussières + obligations haussières"},{"id":"b","label":"Croissance faible + inflation élevée"},{"id":"c","label":"Croissance forte + inflation nulle"},{"id":"d","label":"Déflation + chômage faible"}]'::jsonb, 'b', 'Stagflation = stagnation économique + inflation persistante.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ6', 'analyse-fondamentale', 'intro', 2, 'Dans le MarketDriverVisualizer, si le driver sélectionné est « NFP fort », le canal de transmission vers l''USD est :', '[{"id":"a","label":"Politique fiscale"},{"id":"b","label":"Politique monétaire (taux réels, anticipations Fed)"},{"id":"c","label":"Balance commerciale"},{"id":"d","label":"Rien, le NFP n''impacte pas l''USD"}]'::jsonb, 'b', 'NFP fort → Fed hawkish → taux ↑ → USD ↑.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ7', 'analyse-fondamentale', 'intro', 2, 'Le MacroRegimeRadar utilise un polygone à 6 axes. Lequel de ces axes n''est PAS affiché ?', '[{"id":"a","label":"PIB"},{"id":"b","label":"Inflation"},{"id":"c","label":"Taux directeurs"},{"id":"d","label":"Dividendes"}]'::jsonb, 'd', 'Les 6 axes sont : PIB, IPC, Taux, Liquidité, Sentiment, Crédit.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ8', 'analyse-fondamentale', 'intro', 3, 'Si le radar indique un score élevé sur « Inflation » et « Taux », mais faible sur « PIB », le régime probable est :', '[{"id":"a","label":"Expansion"},{"id":"b","label":"Stagflation"},{"id":"c","label":"Goldilocks"},{"id":"d","label":"Récession pure"}]'::jsonb, 'b', 'Inflation haute + croissance faible = Stagflation.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ9', 'analyse-fondamentale', 'intro', 3, 'Dans le MarketDriverVisualizer, l''invalidation d''un driver « PIB fort » pourrait être :', '[{"id":"a","label":"Une révision à la baisse du PIB"},{"id":"b","label":"Une hausse des salaires"},{"id":"c","label":"Une baisse du chômage"},{"id":"d","label":"Un excédent commercial"}]'::jsonb, 'a', 'Si le PIB est révisé à la baisse, la thèse de croissance forte s''effondre.', 'MarketDriverVisualizer', 'a17', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.1-WQ10', 'analyse-fondamentale', 'intro', 3, 'Pourquoi le MacroRegimeRadar est-il plus utile qu''un indicateur macro isolé ?', '[{"id":"a","label":"Parce qu''il est plus coloré"},{"id":"b","label":"Parce qu''il force la lecture multi-dimensionnelle (croisement de plusieurs facteurs)"},{"id":"c","label":"Parce qu''il prédit le cours exact"},{"id":"d","label":"Parce qu''il remplace l''analyse technique"}]'::jsonb, 'b', 'La macro est multi-factorielle ; le radar évite le diagnostic mono-variable.', 'MacroRegimeRadar', 'a11', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ1', 'analyse-fondamentale', 'macro', 1, 'Le MacroDashboard affiche 11 indicateurs sous forme de :', '[{"id":"a","label":"Graphique linéaire unique"},{"id":"b","label":"Tuiles synthèse (Réel / Consensus / Précédent)"},{"id":"c","label":"Tableau Excel"},{"id":"d","label":"Carte géographique"}]'::jsonb, 'b', 'C''est un command center avec filtres par catégorie et modal détail.', 'MacroDashboard', 'a5', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ2', 'analyse-fondamentale', 'macro', 1, 'Dans l''EconomicCycleWheel, la phase « Récession » favorise généralement :', '[{"id":"a","label":"Les actions cycliques"},{"id":"b","label":"L''or et les obligations souveraines"},{"id":"c","label":"Les devises des marchés émergents"},{"id":"d","label":"Les matières premières industrielles"}]'::jsonb, 'b', 'Récession = fuite vers la qualité (safe havens).', 'EconomicCycleWheel', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ3', 'analyse-fondamentale', 'macro', 1, 'Le FedSimulator utilise deux sliders principaux :', '[{"id":"a","label":"PIB et balance commerciale"},{"id":"b","label":"CPI et NFP"},{"id":"c","label":"Or et pétrole"},{"id":"d","label":"Actions et obligations"}]'::jsonb, 'b', 'La matrice décision Fed croise inflation et emploi.', 'FedSimulator', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ4', 'analyse-fondamentale', 'macro', 2, 'Dans le NfpInterpreter, une surprise de +2σ (sigma) est interprétée comme :', '[{"id":"a","label":"Un bruit statistique"},{"id":"b","label":"Un signal fort susceptible de déclencher une réaction Fed"},{"id":"c","label":"Sans impact sur les marchés"},{"id":"d","label":"Un indicateur retardé"}]'::jsonb, 'b', '>2σ = magnitude exceptionnelle = réaction institutionnelle probable.', 'NfpInterpreter', 'a4', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ5', 'analyse-fondamentale', 'macro', 2, 'Le YieldCurveVisualizer affiche une courbe « inversée » quand :', '[{"id":"a","label":"Les taux longs sont supérieurs aux taux courts"},{"id":"b","label":"Les taux courts sont supérieurs aux taux longs (ex: 2Y > 10Y)"},{"id":"c","label":"Tous les taux sont nuls"},{"id":"d","label":"La Fed baisse les taux"}]'::jsonb, 'b', 'Inversion 2Y/10Y = signal récession classique.', 'YieldCurveVisualizer', 'a14', true);INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ6', 'analyse-fondamentale', 'macro', 2, 'Dans le GdpCpiInterpreters, la combinaison PIB fort + CPI bas correspond au régime :', '[{"id":"a","label":"Stagflation"},{"id":"b","label":"Goldilocks"},{"id":"c","label":"Récession"},{"id":"d","label":"Hyperinflation"}]'::jsonb, 'b', 'Croissance saine + inflation maîtrisée = environnement idéal.', 'GdpCpiInterpreters', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ7', 'analyse-fondamentale', 'macro', 2, 'L''IntermarketCorrelationMap affiche une corrélation négative (rouge) entre DXY et EUR/USD. Cela signifie :', '[{"id":"a","label":"Quand le dollar monte, l''euro tend à baisser"},{"id":"b","label":"Les deux montent ensemble"},{"id":"c","label":"Aucun lien entre les deux"},{"id":"d","label":"La corrélation est décorative"}]'::jsonb, 'a', 'Corrélation négative = mouvements inverses.', 'IntermarketCorrelationMap', 'a13', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ8', 'analyse-fondamentale', 'macro', 2, 'Dans le MacroIndicatorLab, la « surprise » est calculée comme :', '[{"id":"a","label":"Consensus − Réel"},{"id":"b","label":"Réel − Consensus"},{"id":"c","label":"Réel + Consensus"},{"id":"d","label":"Réel / Consensus"}]'::jsonb, 'b', 'Surprise = Réel − Consensus (beat si > 0, miss si < 0).', 'MacroIndicatorLab', 'a2', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ9', 'analyse-fondamentale', 'macro', 2, 'Le MacroRelationshipEngine affiche une chaîne : CPI ↑ → Fed hawkish → USD ↑. Le mécanisme de transmission est :', '[{"id":"a","label":"La politique monétaire restrictive renforce la devise"},{"id":"b","label":"L''inflation affaiblit toujours la devise"},{"id":"c","label":"La Fed achète des devises"},{"id":"d","label":"Le USD monte sans raison"}]'::jsonb, 'a', 'Hawkish = taux ↑ → attrait des capitaux → devise ↑.', 'MacroRelationshipEngine', 'a2', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ10', 'analyse-fondamentale', 'macro', 2, 'Sur le YieldCurveVisualizer, une courbe « plate » suggère :', '[{"id":"a","label":"Une croissance explosive imminente"},{"id":"b","label":"Une transition ou incertitude économique"},{"id":"c","label":"Une inflation galopante"},{"id":"d","label":"Un défaut souverain"}]'::jsonb, 'b', 'Courbe plate = marché incertain sur la direction future.', 'YieldCurveVisualizer', 'a14', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ11', 'analyse-fondamentale', 'macro', 2, 'Dans le MacroDashboard, un indicateur affichant « Beat » avec un consensus dépassé signifie :', '[{"id":"a","label":"Le réel est inférieur au consensus"},{"id":"b","label":"Le réel est supérieur au consensus"},{"id":"c","label":"Le réel égale le consensus"},{"id":"d","label":"L''indicateur est annulé"}]'::jsonb, 'b', 'Beat = réel > consensus (surprise positive).', 'MacroDashboard', 'a5', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ12', 'analyse-fondamentale', 'macro', 3, 'L''EconomicCycleWheel permet de distinguer :', '[{"id":"a","label":"Le cycle économique (phases macro) de la tendance prix (direction)"},{"id":"b","label":"Le cycle des lave-vaisselle"},{"id":"c","label":"Le PIB et l''inflation uniquement"},{"id":"d","label":"Les taux et les devises"}]'::jsonb, 'a', 'Cycle ≠ tendance. La roue montre les phases macro, pas les graphiques de prix.', 'EconomicCycleWheel', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ13', 'analyse-fondamentale', 'macro', 3, 'Dans le FedSimulator, la combinaison CPI 5 % + NFP 300K produit probablement une décision :', '[{"id":"a","label":"Dovish (baisse des taux)"},{"id":"b","label":"Hawkish (maintien ou hausse des taux)"},{"id":"c","label":"Neutre sans changement"},{"id":"d","label":"QE illimité"}]'::jsonb, 'b', 'Inflation chaude + emploi fort = Fed restrictive.', 'FedSimulator', 'a1', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ14', 'analyse-fondamentale', 'macro', 3, 'Sur l''IntermarketCorrelationMap, une cassure de corrélation historique (gris) entre l''or et le DXY peut signaler :', '[{"id":"a","label":"Un retour à la normale"},{"id":"b","label":"Un choc systémique ou un changement de régime macro"},{"id":"c","label":"Une erreur de données"},{"id":"d","label":"Rien de particulier"}]'::jsonb, 'b', 'Décorrélation soudaine = crise ou changement de paradigme.', 'IntermarketCorrelationMap', 'a13', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.2-WQ15', 'analyse-fondamentale', 'macro', 3, 'Le NfpInterpreter croise le NFP avec les salaires horaires moyens car :', '[{"id":"a","label":"Les salaires sont décoratifs"},{"id":"b","label":"La pression salariale alimente l''inflation (spirale prix-salaires)"},{"id":"c","label":"Les salaires n''ont aucun lien avec la Fed"},{"id":"d","label":"Le NFP seul suffit"}]'::jsonb, 'b', 'NFP + salaires = lecture complète du marché du travail pour la Fed.', 'NfpInterpreter', 'a4', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ1', 'analyse-fondamentale', 'micro', 1, 'Le CompanyHealthScore agrège 4 dimensions. Laquelle n''est PAS incluse ?', '[{"id":"a","label":"Croissance"},{"id":"b","label":"Marges"},{"id":"c","label":"Dette"},{"id":"d","label":"Dividende"}]'::jsonb, 'd', 'Les 4 dimensions sont : Croissance, Marges, Dette, Liquidité.', 'CompanyHealthScore', 'a6', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ2', 'analyse-fondamentale', 'micro', 1, 'Dans le BalanceSheetExplorer, l''équation fondamentale est :', '[{"id":"a","label":"Actif = Passif + Equity"},{"id":"b","label":"Revenus = Bénéfices + Dividendes"},{"id":"c","label":"Dette = Actif − Cash"},{"id":"d","label":"Equity = Dette × ROE"}]'::jsonb, 'a', 'C''est la base de la comptabilité en partie double.', 'BalanceSheetExplorer', 'a8', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ3', 'analyse-fondamentale', 'micro', 1, 'Le CompanyDashboard affiche les KPI sous forme de :', '[{"id":"a","label":"Graphique en camembert"},{"id":"b","label":"Tuiles synthèse avec lecture croisée"},{"id":"c","label":"Tableau Excel brut"},{"id":"d","label":"Carte géographique"}]'::jsonb, 'b', 'C''est une vue synthèse rapide pour le diagnostic micro.', 'CompanyDashboard', 'a3', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ4', 'analyse-fondamentale', 'micro', 2, 'Un score CompanyHealthScore > 75 est interprété comme :', '[{"id":"a","label":"Un red flag immédiat"},{"id":"b","label":"Une qualité institutionnelle"},{"id":"c","label":"Une valorisation excessive"},{"id":"d","label":"Un risque de faillite"}]'::jsonb, 'b', '> 75 = entreprise solide sur les 4 dimensions.', 'CompanyHealthScore', 'a6', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ5', 'analyse-fondamentale', 'micro', 2, 'Dans le FinancialRatios, un ROE > 15 % est généralement considéré comme :', '[{"id":"a","label":"Faible"},{"id":"b","label":"De qualité institutionnelle"},{"id":"c","label":"Négatif"},{"id":"d","label":"Sans importance"}]'::jsonb, 'b', 'Seuil classique de rentabilité des fonds propres.', 'FinancialRatios', 'a7', true);INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ6', 'analyse-fondamentale', 'micro', 2, 'Le Current Ratio dans le FinancialRatios mesure :', '[{"id":"a","label":"La rentabilité"},{"id":"b","label":"La liquidité à court terme (actifs courants / dettes courantes)"},{"id":"c","label":"L''endettement total"},{"id":"d","label":"La croissance"}]'::jsonb, 'b', '< 1 = risque de défaut à court terme.', 'FinancialRatios', 'a7', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ7', 'analyse-fondamentale', 'micro', 2, 'Dans le BalanceSheetExplorer, si Actif < Passif, l''entreprise est :', '[{"id":"a","label":"Très rentable"},{"id":"b","label":"Techniquement insolvable"},{"id":"c","label":"En croissance"},{"id":"d","label":"Sous-évaluée"}]'::jsonb, 'b', 'L''équilibre comptable est rompu = insolvabilité technique.', 'BalanceSheetExplorer', 'a8', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ8', 'analyse-fondamentale', 'micro', 2, 'Le CompanyDashboard suggère qu''un seul KPI « ne raconte rien ». Pourquoi ?', '[{"id":"a","label":"Parce que les KPI sont faux"},{"id":"b","label":"Parce qu''il faut croiser Croissance + Marges + Dette + Cash"},{"id":"c","label":"Parce que le dashboard est inutile"},{"id":"d","label":"Parce que les marchés sont efficients"}]'::jsonb, 'b', 'La microéconomie exige la lecture croisée (ex: profitable + surendetté = fragile).', 'CompanyDashboard', 'a3', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ9', 'analyse-fondamentale', 'micro', 2, 'Un D/E < 1 dans le FinancialRatios indique :', '[{"id":"a","label":"Plus de fonds propres que de dette"},{"id":"b","label":"Plus de dette que de fonds propres"},{"id":"c","label":"Une absence totale de dette"},{"id":"d","label":"Une faillite imminente"}]'::jsonb, 'a', 'Structure financière conservative.', 'FinancialRatios', 'a7', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ10', 'analyse-fondamentale', 'micro', 3, 'Pourquoi le ROE élevé via levier (dette) est-il signalé comme « fragile » dans le FinancialRatios ?', '[{"id":"a","label":"Parce que la dette augmente le risque financier en cas de choc"},{"id":"b","label":"Parce que la dette est interdite"},{"id":"c","label":"Parce que le ROE est faux"},{"id":"d","label":"Parce que les actionnaires préfèrent le cash"}]'::jsonb, 'a', 'ROE artificiellement gonflé = risque de faillite si les taux montent.', 'FinancialRatios', 'a7', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ11', 'analyse-fondamentale', 'micro', 3, 'Dans le BalanceSheetExplorer, le « Current Ratio » < 1 signifie concrètement :', '[{"id":"a","label":"L''entreprise ne peut pas couvrir ses dettes à court terme avec ses actifs liquides"},{"id":"b","label":"L''entreprise est très rentable"},{"id":"c","label":"L''entreprise a trop de cash"},{"id":"d","label":"Rien de particulier"}]'::jsonb, 'a', 'C''est un signal d''alerte de liquidité.', 'BalanceSheetExplorer', 'a8', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.3-WQ12', 'analyse-fondamentale', 'micro', 3, 'Pourquoi le CompanyHealthScore pondère-t-il la « Croissance » à 30 % et la « Liquidité » à 20 % ?', '[{"id":"a","label":"Parce que la croissance est le meilleur prédicteur de création de valeur à long terme"},{"id":"b","label":"Parce que la liquidité n''a pas d''importance"},{"id":"c","label":"Parce que les pondérations sont aléatoires"},{"id":"d","label":"Parce que la dette est plus importante"}]'::jsonb, 'a', 'La croissance est le moteur principal, mais la liquidité reste critique (20 %).', 'CompanyHealthScore', 'a6', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ1', 'analyse-fondamentale', 'outils', 1, 'Le ValuationLab permet de tester :', '[{"id":"a","label":"Les ratios de liquidité"},{"id":"b","label":"Les multiples P/E, P/S, P/B et leur prime/décote sectorielle"},{"id":"c","label":"Les taux de change"},{"id":"d","label":"L''inflation"}]'::jsonb, 'b', 'C''est un laboratoire de valorisation par multiples.', 'ValuationLab', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ2', 'analyse-fondamentale', 'outils', 1, 'Dans le DcfSimulator, le paramètre le plus sensible est :', '[{"id":"a","label":"La croissance des revenus"},{"id":"b","label":"Le WACC"},{"id":"c","label":"La marge nette"},{"id":"d","label":"Le nombre d''employés"}]'::jsonb, 'b', '+1 % WACC = −15 à −20 % valorisation.', 'DcfSimulator', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ3', 'analyse-fondamentale', 'outils', 1, 'Le PeerComparisonMatrix compare une entreprise à :', '[{"id":"a","label":"Des concurrents du même secteur"},{"id":"b","label":"Des entreprises aléatoires"},{"id":"c","label":"Des indices boursiers"},{"id":"d","label":"Des banques centrales"}]'::jsonb, 'a', 'C''est la comparaison avec des pairs (peers).', 'PeerComparisonMatrix', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ4', 'analyse-fondamentale', 'outils', 2, 'Dans l''EarningsImpactEngine, un « Beat + Guidance Lowered » est généralement interprété comme :', '[{"id":"a","label":"Très positif"},{"id":"b","label":"Souvent négatif (le marché privilégie les perspectives)"},{"id":"c","label":"Neutre"},{"id":"d","label":"Sans impact"}]'::jsonb, 'b', 'La guidance > beat actuel. Lowered = dégradation attendue.', 'EarningsImpactEngine', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ5', 'analyse-fondamentale', 'outils', 2, 'Le DcfSimulator affiche la « valeur terminale » comme représentant :', '[{"id":"a","label":"5 % de la valorisation"},{"id":"b","label":"60-80 % de la valorisation totale"},{"id":"c","label":"La dette nette"},{"id":"d","label":"Les dividendes"}]'::jsonb, 'b', 'La majorité de la valeur vient des flux lointains.', 'DcfSimulator', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ6', 'analyse-fondamentale', 'outils', 2, 'Dans le ValuationLab, un multiple supérieur à la médiane sectorielle signifie :', '[{"id":"a","label":"Une décote automatique"},{"id":"b","label":"Une prime (croissance ou qualité supérieure)"},{"id":"c","label":"Une erreur de calcul"},{"id":"d","label":"Un red flag"}]'::jsonb, 'b', 'Prime justifiée par des fondamentaux supérieurs.', 'ValuationLab', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ7', 'analyse-fondamentale', 'outils', 2, 'Le PeerComparisonMatrix identifie un « laggard » comme :', '[{"id":"a","label":"Une entreprise avec ROE élevé et marges supérieures"},{"id":"b","label":"Une entreprise avec multiples bas et marges compressées"},{"id":"c","label":"Une entreprise en forte croissance"},{"id":"d","label":"Une entreprise sans dette"}]'::jsonb, 'b', 'Laggard = sous-performeur structurel du secteur.', 'PeerComparisonMatrix', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ8', 'analyse-fondamentale', 'outils', 2, 'Dans l''EarningsImpactEngine, une surprise EPS > 5 % est considérée comme :', '[{"id":"a","label":"Un bruit de marché"},{"id":"b","label":"Un fort signal"},{"id":"c","label":"Sans importance"},{"id":"d","label":"Un dividende exceptionnel"}]'::jsonb, 'b', '> 5 % = magnitude significative = réaction cours probable.', 'EarningsImpactEngine', 'a12', true);INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ9', 'analyse-fondamentale', 'outils', 3, 'Pourquoi le ValuationLab suggère-t-il de tester la sensibilité EPS ± 10 % ?', '[{"id":"a","label":"Parce que les résultats sont toujours faux"},{"id":"b","label":"Pour évaluer la robustesse de la valorisation face à l''incertitude"},{"id":"c","label":"Parce que c''est obligatoire"},{"id":"d","label":"Pour augmenter le P/E"}]'::jsonb, 'b', 'Le stress testing des hypothèses est central en institutionnel.', 'ValuationLab', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ10', 'analyse-fondamentale', 'outils', 3, 'Dans le DcfSimulator, un taux de croissance perpétuel de 6 % est :', '[{"id":"a","label":"Conservateur"},{"id":"b","label":"Agressif et probablement excessif"},{"id":"c","label":"Standard"},{"id":"d","label":"Interdit"}]'::jsonb, 'b', 'La croissance perpétuelle ne peut excéder la croissance économique long terme (2-4 %).', 'DcfSimulator', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ11', 'analyse-fondamentale', 'outils', 3, 'Le PeerComparisonMatrix peut révéler un « value trap » quand :', '[{"id":"a","label":"Le P/E est bas mais la croissance est négative et la dette élevée"},{"id":"b","label":"Le P/E est élevé"},{"id":"c","label":"L''entreprise est leader"},{"id":"d","label":"Le secteur est en expansion"}]'::jsonb, 'a', 'Multiple bas justifié par la dégradation = pas d''opportunité.', 'PeerComparisonMatrix', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.4-WQ12', 'analyse-fondamentale', 'outils', 3, 'Pourquoi l''EarningsImpactEngine croise-t-il le beat/miss avec la guidance ?', '[{"id":"a","label":"Parce que la guidance oriente les attentes futures plus que le passé"},{"id":"b","label":"Parce que le passé n''a pas d''importance"},{"id":"c","label":"Parce que la guidance est obligatoire"},{"id":"d","label":"Parce que le beat est toujours positif"}]'::jsonb, 'a', 'Le marché est forward-looking. La guidance pilote le réajustement des modèles.', 'EarningsImpactEngine', 'a12', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ1', 'analyse-fondamentale', 'previsions', 1, 'Le ForecastScenarioPlanner utilise :', '[{"id":"a","label":"Un seul scénario"},{"id":"b","label":"3 scénarios (optimiste, neutre, pessimiste) + probabilités"},{"id":"c","label":"10 scénarios identiques"},{"id":"d","label":"Aucun scénario"}]'::jsonb, 'b', 'La valeur espérée = Σ(probabilité × valorisation scénario).', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ2', 'analyse-fondamentale', 'previsions', 1, 'Dans le ScenarioBuilder, un scénario valide doit contenir :', '[{"id":"a","label":"Uniquement une thèse haussière"},{"id":"b","label":"Thèse + mécanisme + catalyseur + invalidation"},{"id":"c","label":"Un graphique technique"},{"id":"d","label":"Un ordre d''achat"}]'::jsonb, 'b', 'Scénario = pourquoi + comment + quand + sortie.', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ3', 'analyse-fondamentale', 'previsions', 1, 'La somme des probabilités des 3 scénarios dans le ForecastScenarioPlanner doit être :', '[{"id":"a","label":"50 %"},{"id":"b","label":"100 %"},{"id":"c","label":"150 %"},{"id":"d","label":"Variable"}]'::jsonb, 'b', 'C''est une distribution de probabilités complète.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ4', 'analyse-fondamentale', 'previsions', 2, 'Le ScenarioBuilder force à définir une « invalidation » car :', '[{"id":"a","label":"C''est une règle de l''AMF"},{"id":"b","label":"Sans invalidation = biais de confirmation, pas un vrai scénario"},{"id":"c","label":"Les stops sont obligatoires"},{"id":"d","label":"L''invalidation est optionnelle"}]'::jsonb, 'b', 'Définir la sortie avant l''entrée = discipline institutionnelle.', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ5', 'analyse-fondamentale', 'previsions', 2, 'Si la valeur espérée > cours actuel dans le ForecastScenarioPlanner, cela suggère :', '[{"id":"a","label":"Une asymétrie positive (upside)"},{"id":"b","label":"Une surévaluation"},{"id":"c","label":"Un scénario sans risque"},{"id":"d","label":"Une erreur de calcul"}]'::jsonb, 'a', 'L''asymétrie risque/rendement favorise l''achat.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ6', 'analyse-fondamentale', 'previsions', 2, 'Dans le ScenarioBuilder, le « catalyseur » correspond à :', '[{"id":"a","label":"Le moment précis où la thèse se déclenche"},{"id":"b","label":"La couleur du graphique"},{"id":"c","label":"Le dividende"},{"id":"d","label":"Le ratio D/E"}]'::jsonb, 'a', 'Quand = événement déclencheur (publication, décision politique).', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ7', 'analyse-fondamentale', 'previsions', 2, 'Pourquoi le ForecastScenarioPlanner exige-t-il 3 scénarios et non 1 ?', '[{"id":"a","label":"Parce que 1 scénario = absence de gestion du risque"},{"id":"b","label":"Parce que la loi l''exige"},{"id":"c","label":"Parce que les marchés sont prévisibles"},{"id":"d","label":"Parce que 3 est un chiffre magique"}]'::jsonb, 'a', 'La préparation multi-scénarios = anticipation des différents états du monde.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ8', 'analyse-fondamentale', 'previsions', 2, 'Dans le ScenarioBuilder, la « validation » d''un scénario correspond à :', '[{"id":"a","label":"L''acceptation par la banque centrale"},{"id":"b","label":"Les conditions confirmant que la thèse se matérialise"},{"id":"c","label":"Un algorithme"},{"id":"d","label":"Un consensus d''analystes"}]'::jsonb, 'b', 'C''est le miroir de l''invalidation : quand est-ce que je sais que j''ai raison ?', 'ScenarioBuilder', 'a9', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ9', 'analyse-fondamentale', 'previsions', 3, 'Une probabilité de 70 % au scénario neutre et 15 % aux extrêmes dans le ForecastScenarioPlanner suggère :', '[{"id":"a","label":"Une confiance élevée dans le scénario central"},{"id":"b","label":"Une incertitude extrême"},{"id":"c","label":"Un marché efficient"},{"id":"d","label":"Une erreur de modélisation"}]'::jsonb, 'a', 'Distribution concentrée = faible volatilité attendue, scénario central dominant.', 'ForecastScenarioPlanner', 'a15', true);
INSERT INTO question_bank_part_b (question_key, chapter_id, lesson_id, difficulty, prompt, choices, correct_id, explanation, widget, visual_id, is_active) VALUES ('1.5-WQ10', 'analyse-fondamentale', 'previsions', 3, 'Pourquoi le ScenarioBuilder inclut-il une étape « export » du scénario ?', '[{"id":"a","label":"Pour le partager et le suivre dans un journal de trading"},{"id":"b","label":"Pour l''imprimer en couleur"},{"id":"c","label":"Parce que c''est obligatoire"},{"id":"d","label":"Pour le vendre"}]'::jsonb, 'a', 'L''export permet le suivi, la rétrospective et l''amélioration du processus décisionnel.', 'ScenarioBuilder', 'a9', true);